import hashlib
import hmac

def verify_onboarding_token(token: str, employee_id: str, signing_key: bytes) -> bool:
    if token.count('.') != 1:
        return False
    token_employee, signature = token.split('.')
    if token_employee != employee_id or len(signature) != 64:
        return False
    try:
        bytes.fromhex(signature)
    except ValueError:
        return False
    expected = hmac.new(signing_key, employee_id.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

