import secrets

def generate_bin_access_code(bin_id: str) -> str:
    if not isinstance(bin_id, str):
        raise ValueError('bin_id must be a string')
    normalized = bin_id.strip().upper()
    if not normalized or any((character not in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-' for character in normalized)):
        raise ValueError('invalid bin_id')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(8)))
    return f'BIN-{normalized}-{code}'

