def verify_loan_receipt(receipt: str, key: bytes) -> tuple[str, str, str]:
    parts = receipt.split(';')
    if len(parts) != 4:
        raise ValueError('invalid receipt')
    book_id, member_id, due_date, supplied = parts
    if not book_id or not member_id:
        raise ValueError('invalid receipt')
    try:
        datetime.date.fromisoformat(due_date)
    except ValueError as exc:
        raise ValueError('invalid receipt') from exc
    payload = f'{book_id};{member_id};{due_date}'.encode('utf-8')
    expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid receipt')
    return (book_id, member_id, due_date)

