def save_port_schedule(base_dir: str, relative_name: str, assignments: dict[str, int]) -> str:
    base = Path(os.path.abspath(base_dir)).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('filename is outside base directory')
    for port in assignments.values():
        if not isinstance(port, int) or isinstance(port, bool) or (not 1 <= port <= 65535):
            raise ValueError('invalid port')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', encoding='utf-8') as output:
        for name in sorted(assignments):
            output.write(f'{name}: {assignments[name]}\n')
    return str(target)

