from pathlib import Path

def write_points_statement(base_dir: str, filename: str, member_id: str, points: int) -> str:
    if points < 0:
        raise ValueError('points must be nonnegative')
    base = Path(base_dir).resolve()
    target = (base / filename).resolve()
    if target != base and base not in target.parents:
        raise ValueError('filename is outside the base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(f'Member: {member_id}\nPoints: {points}\n')
    return str(target)

import xml.etree.ElementTree as ET

def parse_route(xml_text: str) -> list[tuple[int, str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'route':
        raise ValueError('root must be route')
    stops = []
    orders = set()
    for element in root.findall('stop'):
        try:
            order = int(element.attrib['order'])
            address = element.attrib['address']
            package_id = element.attrib['package_id']
        except (KeyError, ValueError) as exc:
            raise ValueError('invalid stop') from exc
        if order < 0 or order in orders:
            raise ValueError('invalid stop order')
        orders.add(order)
        stops.append((order, address, package_id))
    return sorted(stops)

