import io
import xml.sax
import xml.sax.handler

class _RouteHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.depth = 0
        self.root = None
        self.stops = []

    def startElement(self, name, attrs):
        if self.depth == 0:
            self.root = name
        elif self.depth == 1 and name == 'stop':
            try:
                self.stops.append((int(attrs['order']), attrs['address'], attrs['package_id']))
            except (KeyError, ValueError) as exc:
                raise ValueError('invalid stop') from exc
        self.depth += 1

    def endElement(self, name):
        self.depth -= 1

def parse_route(xml_text: str) -> list[tuple[int, str, str]]:
    handler = _RouteHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'route':
        raise ValueError('root must be route')
    orders = [stop[0] for stop in handler.stops]
    if any((order < 0 for order in orders)) or len(orders) != len(set(orders)):
        raise ValueError('invalid stop order')
    return sorted(handler.stops)

