import os
import tempfile

def export_hearings(hearings: list[dict[str, str]], output_path: str) -> int:
    selected = [hearing for hearing in hearings if hearing['status'] == 'scheduled']
    selected.sort(key=lambda hearing: (hearing['date'], hearing['time']))
    directory = os.path.dirname(os.path.abspath(output_path))
    temporary_path = tempfile.mktemp(dir=directory, prefix='schedule-')
    try:
        with open(temporary_path, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['case_id', 'date', 'time', 'courtroom', 'judge'])
            for hearing in selected:
                writer.writerow([hearing[field] for field in ('case_id', 'date', 'time', 'courtroom', 'judge')])
        os.replace(temporary_path, output_path)
    except Exception:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
        raise
    return len(selected)

