from datetime import date

def check_eligibility(requester: dict, policy: dict, service_date: str) -> dict:
    if requester.get('tenant_id') != policy.get('tenant_id') or (requester.get('id') != policy.get('owner_id') and 'eligibility_admin' not in requester.get('roles', [])):
        raise PermissionError('not permitted')
    try:
        day = date.fromisoformat(service_date)
        start = date.fromisoformat(policy['effective_from'])
        end = date.fromisoformat(policy['effective_to'])
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    if policy['status'] != 'active':
        return {'policy_id': policy['policy_id'], 'member_id': policy['member_id'], 'eligible': False, 'reason': 'inactive'}
    if not start <= day <= end:
        return {'policy_id': policy['policy_id'], 'member_id': policy['member_id'], 'eligible': False, 'reason': 'outside coverage period'}
    return {'policy_id': policy['policy_id'], 'member_id': policy['member_id'], 'eligible': True, 'reason': 'eligible'}

