import ast
import operator

def _evaluate(expression, values):
    try:
        tree = ast.parse(expression, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name) and node.id in values:
                return values[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                left, right = (visit(node.left), visit(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                result = visit(node.values[0])
                for item in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                        return result
                    result = visit(item)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, part in zip(node.ops, node.comparators):
                    right = visit(part)
                    if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
                args = [visit(arg) for arg in node.args]
                if len(args) < 2:
                    raise ValueError
                return min(args) if node.func.id == 'min' else max(args)
            raise ValueError
        return visit(tree)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError from exc

