import xml.etree.ElementTree as ET

def active_devices(xml_text: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'registry':
        raise ValueError('invalid root element')
    devices = []
    for element in root:
        if element.tag != 'device':
            continue
        required = ('id', 'name', 'type', 'status')
        if any((name not in element.attrib for name in required)):
            raise ValueError('missing device attribute')
        if element.attrib['status'] == 'active':
            devices.append({'id': element.attrib['id'], 'name': element.attrib['name'], 'type': element.attrib['type']})
    return sorted(devices, key=lambda device: device['id'])

