    for item in deductions:
        if not isinstance(item, dict) or not isinstance(item.get('category'), str):
            raise ValueError('invalid deduction')
        amount = item.get('amount')
        if not isinstance(amount, (int, float)) or isinstance(amount, bool) or amount < 0:
            raise ValueError('invalid deduction')
        checked.append(item)
    ordered = sorted(checked, key=lambda item: item['amount'], reverse=True)
    return {'taxpayer': taxpayer, 'total_deductions': sum((item['amount'] for item in checked)), 'deductions': ordered}

