import xml.etree.ElementTree as ET

def parse_sensor_alert(xml_text: str) -> dict:
    root = ET.fromstring(xml_text)
    if root.tag != 'alert':
        raise ValueError('root must be alert')
    alert_id = root.attrib['id']
    magnitude = float(root.attrib['magnitude'])
    region = root.attrib['region']
    if magnitude < 0:
        raise ValueError('magnitude must not be negative')
    sensors = []
    for element in root:
        if element.tag != 'sensor':
            continue
        sensors.append({'code': element.attrib['code'], 'intensity': float(element.attrib['intensity'])})
    sensors.sort(key=lambda item: item['code'])
    return {'id': alert_id, 'magnitude': magnitude, 'region': region, 'sensors': sensors}

