import xml.sax.handler

class _AlertHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        self.alert = None
        self.sensors = []

    def startElement(self, name, attrs):
        if name == 'alert':
            self.alert = {'id': attrs['id'], 'magnitude': float(attrs['magnitude']), 'region': attrs['region']}
        elif name == 'sensor':
            self.sensors.append({'code': attrs['code'], 'intensity': float(attrs['intensity'])})

def parse_sensor_alert(xml_text: str) -> dict:
    handler = _AlertHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    parser.parse(io.StringIO(xml_text))
    if handler.alert is None:
        raise ValueError('root must be alert')
    if handler.alert['magnitude'] < 0:
        raise ValueError('magnitude must not be negative')
    handler.sensors.sort(key=lambda item: item['code'])
    handler.alert['sensors'] = handler.sensors
    return handler.alert

