import hmac

def verify_attestation(attestation: str, signing_key: bytes) -> bool:
    parts = attestation.split('|')
    if len(parts) != 4:
        return False
    policy_id, status, timestamp, signature = parts
    if not policy_id or status not in {'approved', 'declined'}:
        return False
    if len(timestamp) != 10 or not all(('0' <= char <= '9' for char in timestamp)):
        return False
    body = '|'.join(parts[:3]).encode('utf-8')
    expected = hmac.new(signing_key, body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, expected)

