import ast
import operator

def _evaluate(expression, values):
    tree = ast.parse(expression, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp):
            operations = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in operations:
                raise ValueError('unsupported expression')
            return operations[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.USub):
                return -visit(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +visit(node.operand)
            if isinstance(node.op, ast.Not):
                return not visit(node.operand)
        if isinstance(node, ast.BoolOp):
            values_seen = [visit(item) for item in node.values]
            if isinstance(node.op, ast.And):
                return all(values_seen)
            if isinstance(node.op, ast.Or):
                return any(values_seen)
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            checks = []
            operations = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            for op, item in zip(node.ops, node.comparators):
                if type(op) not in operations:
                    raise ValueError('unsupported expression')
                right = visit(item)
                checks.append(operations[type(op)](left, right))
                left = right
            return all(checks)
        raise ValueError('unsupported expression')
    return visit(tree)

def prioritize_risks(records: list[dict[str, object]], rule: str, score: str) -> list[dict[str, object]]:
    ranked = []
    for index, record in enumerate(records):
        if _evaluate(rule, record):
            ranked.append((_evaluate(score, record), index, record))
    ranked.sort(key=lambda item: (-item[0], item[1]))
    return [item[2] for item in ranked]

