import ast
import operator

class _Evaluator(ast.NodeVisitor):
    names = {'age', 'district', 'active'}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def __init__(self, values):
        self.values = values

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_Constant(self, node):
        if isinstance(node.value, (int, float, bool)):
            return node.value
        raise ValueError('invalid rule')

    def visit_Name(self, node):
        if node.id not in self.names:
            raise ValueError('unknown name')
        return self.values[node.id]

    def visit_BinOp(self, node):
        for kind, function in self.binary.items():
            if isinstance(node.op, kind):
                return function(self.visit(node.left), self.visit(node.right))
        raise ValueError('invalid operator')

    def visit_UnaryOp(self, node):
        value = self.visit(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        raise ValueError('invalid operator')

    def visit_BoolOp(self, node):
        values = [self.visit(value) for value in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError('invalid operator')

    def visit_Compare(self, node):
        left = self.visit(node.left)
        for operation, comparator in zip(node.ops, node.comparators):
            right = self.visit(comparator)
            function = next((f for k, f in self.comparisons.items() if isinstance(operation, k)), None)
            if function is None or not function(left, right):
                return False
            left = right
        return True

    def generic_visit(self, node):
        raise ValueError('invalid rule')

def filter_voters(records: list[dict[str, object]], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval')
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc
    result = []
    for record in records:
        if _Evaluator(record).visit(tree):
            result.append(record['id'])
    return result

