def _digest(pin: str, salt: bytes) -> bytes:
    return hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)

def issue_permit(event: str, district: str, pin: str) -> dict:
    event = event.strip()
    district = district.strip()
    if not event or not district or len(pin) != 4 or (not pin.isdecimal()):
        raise ValueError('invalid permit data')
    salt = os.urandom(16)
    access_code = salt.hex() + ':' + _digest(pin, salt).hex()
    return {'event': event, 'district': district, 'access_code': access_code}

def can_view_permit(permit: dict, pin: str) -> bool:
    if not isinstance(permit, dict) or len(pin) != 4 or (not pin.isdecimal()):
        return False
    try:
        salt_text, digest_text = permit['access_code'].split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (KeyError, ValueError, TypeError):
        return False
    return hmac.compare_digest(_digest(pin, salt), expected)

