import xml.etree.ElementTree as ET

def parse_seat_reservations(xml_text: str) -> list[tuple[str, int, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    reservations = []
    for element in root.iter('seat'):
        try:
            row = element.attrib['row']
            number = int(element.attrib['number'])
            customer = element.attrib['customer']
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid seat reservation') from exc
        if number <= 0:
            raise ValueError('seat number must be positive')
        reservations.append((row, number, customer))
    return sorted(reservations, key=lambda item: (item[0], item[1]))

