import os

def hash_pin(pin: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, stored_digest: str) -> bool:
    try:
        salt_text, digest_text = stored_digest.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def calculate_cart_total(items: list[tuple[str, int, int]], pin: str | None, stored_digest: str | None) -> int:
    total = 0
    for _, price, quantity in items:
        if price < 0 or quantity < 0:
            raise ValueError('price and quantity must be non-negative')
        total += price * quantity
    if pin is not None and stored_digest is not None and verify_pin(pin, stored_digest):
        total -= total // 10
    return total

