def parse_inventory(xml_text: str) -> list[dict[str, object]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    records = []
    for element in root.findall('sample'):
        try:
            sample_id = element.attrib['id']
            kind = element.attrib['kind']
            quantity = int(element.attrib['quantity'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid sample') from exc
        if quantity < 0:
            raise ValueError('invalid sample')
        records.append({'id': sample_id, 'kind': kind, 'quantity': quantity})
    return sorted(records, key=lambda record: record['id'])

