def update_listing_status(requester: dict, listings: list[dict], listing_id: str, status: str) -> dict:
    if status not in {'draft', 'published', 'sold'}:
        raise ValueError('unsupported status')
    for listing in listings:
        if listing['id'] == listing_id:
            permitted = listing['owner_id'] == requester['id']
            permitted = permitted or (requester['role'] == 'admin' and requester['tenant_id'] == listing['tenant_id'])
            if not permitted:
                raise PermissionError('not permitted')
