import os
import subprocess

def read_station_temperatures(path: str, station: str) -> list[float]:
    if not station:
        raise ValueError('station must not be empty')
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    result = subprocess.run(['grep', '-F', '--', f'{station},', path], capture_output=True, text=True, check=False)
    if result.returncode not in (0, 1):
        raise FileNotFoundError(path)
    temperatures = []
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        name, value = line.split(',', 1)
        if name == station:
            try:
                temperatures.append(float(value))
            except ValueError as exc:
                raise ValueError('invalid temperature') from exc
    return sorted(temperatures)

