import ast
import operator

def _evaluate(rule, values):
    tree = ast.parse(rule, mode='eval').body
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    compare = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in values:
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            if isinstance(node.op, ast.And):
                result = True
                for part in node.values:
                    result = result and visit(part)
                    if not result:
                        break
                return result
            result = False
            for part in node.values:
                result = result or visit(part)
                if result:
                    break
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for operation, right_node in zip(node.ops, node.comparators):
                right = visit(right_node)
                if type(operation) not in compare or not compare[type(operation)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*[visit(arg) for arg in node.args])
        raise ValueError('invalid rule')
    return visit(tree)

def filter_transactions(transactions: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    try:
        selected = [item for item in transactions if _evaluate(rule, {name: item[name] for name in ('amount', 'balance', 'fee')})]
    except (KeyError, SyntaxError, TypeError, ValueError, ZeroDivisionError) as exc:
        raise ValueError('invalid rule') from exc
    return sorted(selected, key=lambda item: item['amount'], reverse=True)

