import os

def hash_monitor_token(token: str) -> str:
    if not isinstance(token, str) or not token:
        raise ValueError('token must be a non-empty string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', token.encode(), salt, 100000)
    return base64.urlsafe_b64encode(salt).decode() + '.' + base64.urlsafe_b64encode(digest).decode()

def verify_monitor_token(token: str, stored: str) -> bool:
    if not isinstance(token, str) or not token or (not isinstance(stored, str)):
        return False
    try:
        salt_text, digest_text = stored.split('.', 1)
        salt = base64.urlsafe_b64decode(salt_text.encode())
        expected = base64.urlsafe_b64decode(digest_text.encode())
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', token.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

