            self.parts = []

    def characters(self, content):
        if self.current is not None:
            self.parts.append(content)

    def endElement(self, name):
        if name == self.current:
            self.values[name] = ''.join(self.parts).strip()
            self.current = None
            self.parts = []

def parse_claim(xml_text: str) -> dict[str, object]:
    handler = _ClaimHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'claim':
        raise ValueError('invalid root')
    for name in ('claim_id', 'policy_number', 'amount', 'loss_date'):
        if name not in handler.values or not handler.values[name]:
            raise ValueError('missing field')
    try:
        amount = float(handler.values['amount'])
    except ValueError as exc:
        raise ValueError('invalid amount') from exc
    if amount < 0:
        raise ValueError('invalid amount')
    return {'claim_id': handler.values['claim_id'], 'policy_number': handler.values['policy_number'], 'amount': amount, 'loss_date': handler.values['loss_date']}

