import hashlib
import hmac

def verify_document(package: bytes, secret: bytes) -> tuple[str, bytes]:
    parts = package.split(b'\n', 2)
    if len(parts) != 3:
        raise ValueError('malformed package')
    name_bytes, signature_bytes, content = parts
    try:
        name = name_bytes.decode('utf-8')
        signature = signature_bytes.decode('ascii')
    except UnicodeDecodeError as exc:
        raise ValueError('invalid package text') from exc
    if not name or '/' in name or '\\' in name:
        raise ValueError('invalid filename')
    expected = hmac.new(secret, name_bytes + b'\n' + content, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    return (name, content)

