def calculate_royalties(requester: dict, plays: list[dict], tracks: dict[str, dict]) -> dict[str, float]:
    totals = {}
    for play in plays:
        count = play['count']
        if not isinstance(count, int) or isinstance(count, bool) or count < 0:
            raise ValueError('count must be a non-negative integer')
        track_id = play['track_id']
        track = tracks[track_id]
        allowed = track['tenant_id'] == requester['tenant_id'] and (track['owner_id'] == requester['id'] or requester['role'] == 'royalty_manager')
        if not allowed:
            raise PermissionError('requester cannot obtain this report')
        totals[track_id] = totals.get(track_id, 0) + count * track['rate']
    return {track_id: round(totals[track_id], 2) for track_id in sorted(totals)}

