import xml.etree.ElementTree as ET

def parse_download_report(xml_text: str) -> list[tuple[str, int]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('malformed XML') from exc
    result = []
    for episode in root.findall('episode'):
        title = episode.get('title')
        raw_downloads = episode.get('downloads')
        if title is None or raw_downloads is None:
            raise ValueError('missing episode attribute')
        try:
            downloads = int(raw_downloads)
        except ValueError as exc:
            raise ValueError('downloads must be an integer') from exc
        if downloads < 0:
            raise ValueError('downloads must be non-negative')
        result.append((title, downloads))
    return sorted(result, key=lambda item: (-item[1], item[0]))

