import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id in ('True', 'False'):
            return node.id == 'True'
        if node.id not in names:
            raise NameError(node.id)
        return names[node.id]
    if isinstance(node, ast.BinOp):
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        if type(node.op) not in ops:
            raise ValueError('unsupported operator')
        return ops[type(node.op)](_value(node.left, names), _value(node.right, names))
    if isinstance(node, ast.UnaryOp):
        ops = {ast.Not: operator.not_, ast.UAdd: operator.pos, ast.USub: operator.neg}
        if type(node.op) not in ops:
            raise ValueError('unsupported operator')
        return ops[type(node.op)](_value(node.operand, names))
    if isinstance(node, ast.BoolOp):
        values = [_value(node.values[0], names)]
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not values[-1]):
                return values[-1]
            if isinstance(node.op, ast.Or) and values[-1]:
                return values[-1]
            values.append(_value(child, names))
        return values[-1]
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        checks = []
        ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
        for op, child in zip(node.ops, node.comparators):
            if type(op) not in ops:
                raise ValueError('unsupported comparison')
            right = _value(child, names)
            checks.append(ops[type(op)](left, right))
            left = right
        return all(checks)
    raise ValueError('unsupported expression')

def select_cases(cases: list[dict], rule: str) -> list[dict]:
