import ast
import operator

def _eval(node, values):
    if isinstance(node, ast.Expression):
        return _eval(node.body, values)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError('unknown name')
        return values[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        return ops[type(node.op)](_eval(node.left, values), _eval(node.right, values))
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _eval(node.operand, values)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        result = _eval(node.values[0], values)
        for part in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                return result
            result = _eval(part, values)
        return result
    if isinstance(node, ast.Compare):
        left = _eval(node.left, values)
        checks = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
        for op, item in zip(node.ops, node.comparators):
            right = _eval(item, values)
            if type(op) not in checks or not checks[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_eval(x, values) for x in node.args])
    raise ValueError('invalid rule')

def fulfill(records: list[dict[str, object]], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval')
        chosen = [r for r in records if _eval(tree, r)]
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid rule') from exc
    chosen.sort(key=lambda r: (-r['priority'], r['id']))
    return [r['id'] for r in chosen]

