    if not isinstance(record, str) or not isinstance(document_id, str) or (not isinstance(passphrase, str)):
        return False
    if not document_id or re.fullmatch('[A-Za-z0-9_-]+', document_id) is None or (not passphrase):
        return False
    parts = record.split(':')
