import ast
import operator

def filter_cases(cases: list[dict], rule: str) -> list[dict]:
    tree = ast.parse(rule, mode='eval').body

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp):
            left = evaluate(node.left, values)
            right = evaluate(node.right, values)
            operations = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            for kind, operation in operations.items():
                if isinstance(node.op, kind):
                    return operation(left, right)
        if isinstance(node, ast.UnaryOp):
            value = evaluate(node.operand, values)
            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.Not):
                return not value
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                result = evaluate(node.values[0], values)
                for item in node.values[1:]:
                    if not result:
                        return result
                    result = evaluate(item, values)
                return result
            result = evaluate(node.values[0], values)
            for item in node.values[1:]:
                if result:
                    return result
                result = evaluate(item, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for operation_node, comparator in zip(node.ops, node.comparators):
                right = evaluate(comparator, values)
                operations = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}
                operation = next((fn for kind, fn in operations.items() if isinstance(operation_node, kind)), None)
                if operation is None or not operation(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
            functions = {'min': min, 'max': max, 'round': round}
            return functions[node.func.id](*(evaluate(arg, values) for arg in node.args))
        raise ValueError('unsupported expression')
    return [case for case in cases if evaluate(tree, case)]

