import xml.etree.ElementTree as ET

def parse_lunch_payments(xml_text: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'lunch_payments':
        raise ValueError('unexpected root')
    result = []
    required = {'student_id', 'cents', 'meal_date'}
    for element in root:
        if element.tag != 'payment' or set(element.attrib) != required:
            raise ValueError('invalid payment')
        cents = element.attrib['cents']
        if not cents.isdigit():
            raise ValueError('invalid cents')
        result.append({'student_id': element.attrib['student_id'], 'cents': cents, 'meal_date': element.attrib['meal_date']})
    return sorted(result, key=lambda item: item['student_id'])

