import xml.sax.handler

class _PaymentHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.root_seen = False
        self.payments = []

    def startElement(self, name, attrs):
        if not self.root_seen:
            if name != 'lunch_payments':
                raise ValueError('unexpected root')
            self.root_seen = True
            return
        if name != 'payment' or set(attrs.getNames()) != {'student_id', 'cents', 'meal_date'}:
            raise ValueError('invalid payment')
        cents = attrs['cents']
        if not cents.isdigit():
            raise ValueError('invalid cents')
        self.payments.append({'student_id': attrs['student_id'], 'cents': cents, 'meal_date': attrs['meal_date']})

    def endElement(self, name):
        if name == 'lunch_payments':
            self.root_seen = False

def parse_lunch_payments(xml_text: str) -> list[dict[str, str]]:
    handler = _PaymentHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except (xml.sax.SAXException, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if handler.root_seen:
        raise ValueError('invalid XML')
    return sorted(handler.payments, key=lambda item: item['student_id'])

