def save_monitoring_report(base_dir: str, report_name: str, readings: list[tuple[str, float]]) -> str:
    if not report_name:
        raise ValueError('report name must not be empty')
    base = Path(base_dir).resolve()
    candidate = (base / report_name).resolve()
    try:
        candidate.relative_to(base)
    except ValueError:
        raise ValueError('report must be under base directory')
    candidate.parent.mkdir(parents=True, exist_ok=True)
    ordered = sorted(readings, key=lambda item: item[0])
    candidate.write_text(''.join((f'{timestamp}: {value:.2f}\n' for timestamp, value in ordered)))
    return str(candidate)

