        selected = [r for r in records if _evaluate(tree, {k: r[k] for k in ('score', 'defect_rate', 'sample_size')})]
    except (SyntaxError, KeyError, TypeError, ValueError, ZeroDivisionError, NameError):
        raise ValueError('invalid rule')
    return [r['id'] for r in sorted(selected, key=lambda r: (-r['score'], r['id']))]

