import operator

def select_assets(assets: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError from exc
    variables = {'id', 'cost', 'age', 'available'}
    functions = {'min': min, 'max': max, 'round': round}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in variables:
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = evaluate(child, values)
            return value
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for op, child in zip(node.ops, node.comparators):
                right = evaluate(child, values)
                if type(op) not in comparisons or not comparisons[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
            return functions[node.func.id](*(evaluate(arg, values) for arg in node.args))
        raise ValueError
    result = []
    for asset in assets:
        try:
            if evaluate(tree, asset):
                result.append(asset)
        except Exception as exc:
            if isinstance(exc, ValueError):
                raise
            raise ValueError from exc
    return result

