import xml.etree.ElementTree as ET

def load_ticket_summary(xml_text: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'tickets':
        raise ValueError('invalid root element')
    result = []
    for ticket in root.findall('ticket'):
        values = {'id': ticket.get('id'), 'status': ticket.get('status'), 'customer': ticket.findtext('customer'), 'subject': ticket.findtext('subject')}
        if any((value is None for value in values.values())):
            raise ValueError('incomplete ticket')
        result.append({key: value.strip() for key, value in values.items()})
    return sorted(result, key=lambda item: item['id'])

