import ast

def _evaluate(rule, values):
    try:
        tree = ast.parse(rule, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in values:
                    raise ValueError('unknown name')
                return values[node.id]
            if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
                left, right = (visit(node.left), visit(node.right))
                return {ast.Add: lambda: left + right, ast.Sub: lambda: left - right, ast.Mult: lambda: left * right, ast.Div: lambda: left / right}[type(node.op)]()
            if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.Not, ast.USub, ast.UAdd):
                value = visit(node.operand)
                return not value if isinstance(node.op, ast.Not) else -value if isinstance(node.op, ast.USub) else +value
            if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
                result = visit(node.values[0])
                for item in node.values[1:]:
                    result = visit(item) if isinstance(node.op, ast.And) and result or (isinstance(node.op, ast.Or) and (not result)) else result
                return result
            if isinstance(node, ast.Compare):
                current = visit(node.left)
                for op, part in zip(node.ops, node.comparators):
                    right = visit(part)
                    if type(op) not in (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE):
                        raise ValueError('invalid rule')
                    if not {ast.Eq: current == right, ast.NotEq: current != right, ast.Lt: current < right, ast.LtE: current <= right, ast.Gt: current > right, ast.GtE: current >= right}[type(op)]:
                        return False
                    current = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
            raise ValueError('invalid rule')
        return visit(tree)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid rule') from exc

def filter_attendees(attendees: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
