import xml.sax.handler

class _ReviewHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.items = []
        self.current = None
        self.field = None
        self.parts = []
        self.root = None

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name == 'document':
            self.current = {'id': attrs.get('id'), 'status': attrs.get('status')}
        elif self.current is not None and name in ('title', 'date'):
            self.field = name
            self.parts = []

    def characters(self, content):
        if self.field is not None:
            self.parts.append(content)

    def endElement(self, name):
        if self.current is not None and name in ('title', 'date') and (self.field == name):
            self.current[name] = ''.join(self.parts).strip()
            self.field = None
            self.parts = []
        elif name == 'document':
            if self.current.get('id') is None or self.current.get('status') is None or 'title' not in self.current or ('date' not in self.current):
                raise ValueError('incomplete document')
            self.items.append(self.current)
            self.current = None

def extract_review_items(xml_text: str) -> list[dict[str, str]]:
    handler = _ReviewHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    xml.sax.parseString(xml_text, handler)
    if handler.root != 'review':
        raise ValueError('root must be review')
    return sorted(handler.items, key=lambda item: (-int(item['date'].replace('-', '')), item['id']))

