def get_subject_records(request: str, expected_token: str, records: list[dict]) -> list[dict]:
    fields = request.split('&')
    if len(fields) != 2:
        raise ValueError('invalid request')
    parsed = {}
    for field in fields:
        item = field.split('=', 1)
        if len(item) != 2 or item[0] not in ('token', 'subject') or item[0] in parsed:
            raise ValueError('invalid request')
        parsed[item[0]] = item[1]
    if set(parsed) != {'token', 'subject'} or not parsed['token'] or (not parsed['subject']):
        raise ValueError('invalid request')
    if not hmac.compare_digest(parsed['token'], expected_token):
        raise PermissionError('invalid token')
    subject = parsed['subject']
    return sorted((record for record in records if record['subject'] == subject), key=lambda record: record['created'])

