class _RoomHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.depth = 0
        self.root = None
        self.rooms = []

    def startElement(self, name, attrs):
        if self.depth == 0:
            self.root = name
        elif self.depth == 1 and name == 'room':
            room_id = attrs.get('id', '')
            price_text = attrs.get('price', '')
            available = attrs.get('available')
