import hashlib
import hmac
import os
_ITERATIONS = 100000

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and 4 <= len(pin) <= 8 and pin.isdecimal() and pin.isascii()

def hash_pin(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('PIN must contain four to eight decimal digits')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, _ITERATIONS)
    return salt.hex() + ':' + digest.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not _valid_pin(pin) or not isinstance(stored, str):
        return False
    parts = stored.split(':')
    if len(parts) != 2:
        return False
    try:
        salt = bytes.fromhex(parts[0])
        expected = bytes.fromhex(parts[1])
    except ValueError:
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, _ITERATIONS)
    return hmac.compare_digest(actual, expected)

