import json
from pathlib import Path

def load_eligibility_record(base_dir: str, relative_name: str) -> dict:
    base = Path(base_dir).resolve()
    path = (base / relative_name).resolve()
    try:
        path.relative_to(base)
    except ValueError:
        raise ValueError('record is outside the base directory')
    with path.open(encoding='utf-8') as handle:
        data = json.load(handle)
    if not isinstance(data, dict):
        raise ValueError('record must be an object')
    required = ('member_id', 'eligible', 'plan')
    if any((key not in data for key in required)):
        raise ValueError('record is missing a required field')
    if not isinstance(data['member_id'], str):
        raise ValueError('member_id must be a string')
    if not isinstance(data['eligible'], bool):
        raise ValueError('eligible must be a boolean')
    if not isinstance(data['plan'], str):
        raise ValueError('plan must be a string')
    return {key: data[key] for key in required}

