        try:
            stand_id = stand.attrib['id']
            species = stand.attrib['species']
            area = float(stand.attrib['area'])
            priority = int(stand.attrib['priority'])
            status = stand.attrib['status']
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid stand') from exc
        if status == 'planned':
            result.append((priority, stand_id, species, area))
    result.sort(key=lambda item: -item[0])
    return [(stand_id, species, area) for _, stand_id, species, area in result]

