import ast
import operator

def _evaluate(expression, variables):
    tree = ast.parse(expression, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            return variables[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left, right = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            values = [visit(value) for value in node.values]
            return all(values) if isinstance(node.op, ast.And) else any(values)
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            results = []
            for operation, comparator in zip(node.ops, node.comparators):
                right = visit(comparator)
                results.append({ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(operation)](left, right))
                left = right
            return all(results)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
            values = [visit(argument) for argument in node.args]
            if len(values) < 2:
                raise ValueError('min and max need at least two arguments')
            return min(values) if node.func.id == 'min' else max(values)
        raise ValueError('invalid expression')
    return visit(tree)

def select_localized(entries: list[dict[str, object]], locale: str, rule: str) -> list[str]:
    selected = []
    for entry in entries:
        translations = entry['translations']
        if locale not in translations:
            continue
        text = translations[locale]
        variables = {'score': entry['score'], 'length': len(text), 'has_translation': True}
        if _evaluate(rule, variables):
            selected.append((entry['score'], entry['key'], text))
    selected.sort(key=lambda item: (-item[0], item[1]))
    return [item[2] for item in selected]

