import ast

def filter_members(members: list[dict[str, int | float]], rule: str) -> list[dict[str, int | float]]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left, right = (evaluate(node.left, values), evaluate(node.right, values))
            return left + right if isinstance(node.op, ast.Add) else left - right if isinstance(node.op, ast.Sub) else left * right if isinstance(node.op, ast.Mult) else left / right
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not result:
                        return result
                elif result:
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for operation, child in zip(node.ops, node.comparators):
                right = evaluate(child, values)
                good = left == right if isinstance(operation, ast.Eq) else left != right if isinstance(operation, ast.NotEq) else left < right if isinstance(operation, ast.Lt) else left <= right if isinstance(operation, ast.LtE) else left > right if isinstance(operation, ast.Gt) else left >= right if isinstance(operation, ast.GtE) else False
                if not good:
                    return False
                left = right
            return True
        raise ValueError('unsupported rule')
    return [member for member in members if evaluate(tree, member)]

