import os

def save_visit_note(base_dir: str, relative_name: str, note: str) -> str:
    if not relative_name or not note:
        raise ValueError('relative_name and note must not be empty')
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath((base, target)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('location is outside base directory')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        handle.write(note)
    return target

import subprocess

def median_demand(path: str) -> float:
    result = subprocess.run(['sort', '-n', path], capture_output=True, text=True, check=True)
    values = []
    for line in result.stdout.splitlines():
        line = line.strip()
        if line:
            try:
                values.append(float(line))
            except ValueError as exc:
                raise ValueError('invalid demand value') from exc
    if not values:
        raise ValueError('no numeric values')
    middle = len(values) // 2
    if len(values) % 2:
        return values[middle]
    return (values[middle - 1] + values[middle]) / 2

