            if type(node.op) not in ops:
                raise ValueError('unsupported expression')
            return ops[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return not visit(node.operand)
            if isinstance(node.op, ast.USub):
                return -visit(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +visit(node.operand)
        if isinstance(node, ast.BoolOp):
            value = visit(node.values[0])
            for item in node.values[1:]:
                if isinstance(node.op, ast.And):
                    value = visit(item) if value else value
                else:
                    value = value if value else visit(item)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, part in zip(node.ops, node.comparators):
                right = visit(part)
                funcs = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
