import xml.etree.ElementTree as ET

def rank_leads(xml_text: str) -> list[dict[str, str | int]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'leads':
        raise ValueError('invalid root')
    required = ('name', 'company', 'email', 'score')
    result = []
    for lead in root:
        if lead.tag != 'lead':
            raise ValueError('invalid lead')
        values = {}
        for child in lead:
            if child.tag not in required or child.tag in values:
                raise ValueError('invalid lead field')
            values[child.tag] = (child.text or '').strip()
        if any((field not in values for field in required)):
            raise ValueError('missing lead field')
        try:
            score = int(values['score'])
        except ValueError as exc:
            raise ValueError('invalid score') from exc
        result.append({'name': values['name'], 'company': values['company'], 'email': values['email'], 'score': score})
    return sorted(result, key=lambda item: (-item['score'], item['name']))

