            if name not in ('name', 'company', 'email', 'score') or name in self.current:
                raise ValueError('invalid lead field')
            self.field = name
            self.text = []

    def characters(self, content):
        if self.field is not None:
            self.text.append(content)

    def endElement(self, name):
        if self.field == name:
            self.current[name] = ''.join(self.text).strip()
            self.field = None
            self.text = []
        elif name == 'lead':
            if self.current is None or any((x not in self.current for x in ('name', 'company', 'email', 'score'))):
