import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        raise ValueError('unsupported literal')
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise NameError(node.id)
        return values[node.id]
    if isinstance(node, ast.BinOp):
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        if type(node.op) not in ops:
            raise ValueError('unsupported operator')
        return ops[type(node.op)](_evaluate(node.left, values), _evaluate(node.right, values))
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
        if isinstance(node.op, ast.Not):
            return not value
        raise ValueError('unsupported operator')
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = _evaluate(node.values[0], values)
            for item in node.values[1:]:
                if not result:
                    return result
                result = _evaluate(item, values)
            return result
        result = _evaluate(node.values[0], values)
        for item in node.values[1:]:
            if result:
                return result
            result = _evaluate(item, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        operations = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}
        for op, comparator in zip(node.ops, node.comparators):
            right = _evaluate(comparator, values)
            if type(op) not in operations or not operations[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}):
        if node.keywords:
            raise ValueError('keywords are not supported')
        args = [_evaluate(arg, values) for arg in node.args]
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
    raise ValueError('unsupported expression')

def select_vehicles(vehicles: list[dict[str, object]], rule: str) -> list[str]:
    tree = ast.parse(rule, mode='eval')
    return [vehicle['id'] for vehicle in vehicles if _evaluate(tree.body, vehicle)]

