import hashlib
import hmac
import json
from typing import Mapping

def reconcile_purchases(purchases: list[dict[str, object]], config: Mapping[str, str]) -> dict[str, object]:
    key = config.get('signing_key')
    if key is None:
        raise ValueError('missing signing key')
    items = []
    for purchase in purchases:
        if purchase.get('status') != 'completed':
            continue
        amount = purchase.get('amount')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            raise ValueError('invalid amount')
        items.append({'receipt_id': purchase['receipt_id'], 'player_id': purchase['player_id'], 'amount': amount})
    items.sort(key=lambda item: item['receipt_id'])
    payload = json.dumps(items, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return {'purchases': items, 'total': sum((item['amount'] for item in items)), 'signature': signature}

import base64
import hashlib
import hmac
import os

def create_courier(name: str, pin: str, zone: str) -> dict[str, str]:
    if not name.strip() or not zone.strip():
        raise ValueError('name and zone are required')
    if len(pin) != 4 or not pin.isdecimal() or (not pin.isascii()):
        raise ValueError('PIN must contain four digits')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    credential = base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()
    return {'name': name, 'zone': zone, 'credential': credential}

def authenticate_courier(record: dict[str, str], pin: str) -> bool:
    try:
        salt_text, digest_text = record['credential'].split(':', 1)
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
    except (KeyError, ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

