import base64
import hashlib
import hmac
import os

def hash_registry_token(token: str) -> str:
    if not token:
        raise ValueError('token must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', token.encode('utf-8'), salt, 120000)
    return base64.urlsafe_b64encode(salt).decode('ascii') + '.' + base64.urlsafe_b64encode(digest).decode('ascii')

def verify_registry_token(token: str, stored: str) -> bool:
    if not token or not stored:
        return False
    try:
        salt_text, digest_text = stored.split('.', 1)
        salt = base64.urlsafe_b64decode(salt_text.encode('ascii'))
        expected = base64.urlsafe_b64decode(digest_text.encode('ascii'))
    except (ValueError, UnicodeError, TypeError):
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', token.encode('utf-8'), salt, 120000)
    return hmac.compare_digest(actual, expected)

