import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, values)
    if isinstance(node, ast.Constant) and type(node.value) in (int, float):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise NameError(node.id)
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.USub, ast.UAdd, ast.Not):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return +value
        return not value
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        result = _evaluate(node.values[0], values)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _evaluate(item, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        checks = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, values)
            if not checks[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords) and (len(node.args) >= 2):
        args = [_evaluate(arg, values) for arg in node.args]
        return min(args) if node.func.id == 'min' else max(args)
    raise ValueError('unsupported rule')

def filter_events(events: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    tree = ast.parse(rule, mode='eval')
    return [event for event in events if _evaluate(tree, event)]

