def verify_archive_manifest(manifest: str, secret: bytes) -> tuple[str, list[tuple[str, int]]]:
    lines = manifest.splitlines()
    if not lines or not lines[0].startswith('signature='):
        raise ValueError('invalid manifest')
    signature_text = lines[0][10:]
    try:
        signature = bytes.fromhex(signature_text)
    except ValueError:
        raise ValueError('invalid manifest')
    if len(signature) != hashlib.sha256().digest_size:
        raise ValueError('invalid manifest')
    payload = '\n'.join(lines[1:])
    expected = hmac.digest(secret, payload.encode(), hashlib.sha256)
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid manifest')
    archive = None
    files = []
    for line in lines[1:]:
        if line.startswith('archive='):
            if archive is not None:
                raise ValueError('invalid manifest')
            archive = line[8:]
        elif line.startswith('file=') and '\t' in line:
            path, size_text = line[5:].split('\t', 1)
            try:
                size = int(size_text)
            except ValueError:
                raise ValueError('invalid manifest')
            if size < 0 or not path:
                raise ValueError('invalid manifest')
            files.append((path, size))
        else:
            raise ValueError('invalid manifest')
    if archive is None:
        raise ValueError('invalid manifest')
    files.sort(key=lambda item: item[0])
    return (archive, files)

