    tree = ast.parse(rule, mode='eval')
    selected = []
    for visit in visits:
        names = dict(values)
        names.update(visit)
        if _evaluate(tree, names):
            selected.append(visit)
    return sorted(selected, key=lambda visit: (visit['date'], visit['start']))

