import ast
import operator

def allocate_rooms(rooms: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except (SyntaxError, ValueError):
        raise ValueError('invalid rule')

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in {'min', 'max'}:
                return node.id
            if node.id in current:
                return current[node.id]
            raise ValueError('unknown name')
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left, right = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            values = [visit(value) for value in node.values]
            return all(values) if isinstance(node.op, ast.And) else any(values)
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, part in zip(node.ops, node.comparators):
                right = visit(part)
                if not isinstance(op, (ast.Lt, ast.LtE, ast.Eq, ast.NotEq, ast.Gt, ast.GtE)):
                    raise ValueError('invalid operator')
                if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max'}) and (not node.keywords):
            return min((visit(a) for a in node.args)) if node.func.id == 'min' else max((visit(a) for a in node.args))
        raise ValueError('invalid rule')
    result = []
    for current in rooms:
        try:
            if visit(tree):
                result.append(current)
        except (ArithmeticError, TypeError, ValueError):
            raise ValueError('invalid rule')
    return result

