import hmac
import os

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and pin.isdecimal() and (4 <= len(pin) <= 12)

def hash_station_pin(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_station_pin(pin: str, stored: str) -> bool:
    if not _valid_pin(pin) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

