    try:
        tree = ast.parse(rule, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc

    def evaluate(node, names):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float, str, bool)) or node.value is None:
                return node.value
            raise ValueError('invalid rule')
        if isinstance(node, ast.Name):
            if node.id not in names:
                raise ValueError('unknown name')
            return names[node.id]
        if isinstance(node, ast.BinOp):
            left = evaluate(node.left, names)
            right = evaluate(node.right, names)
            operations = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            for kind, operation in operations.items():
                if isinstance(node.op, kind):
                    return operation(left, right)
            raise ValueError('invalid rule')
        if isinstance(node, ast.UnaryOp):
            value = evaluate(node.operand, names)
            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.Not):
                return not value
            raise ValueError('invalid rule')
        if isinstance(node, ast.BoolOp):
