                result = values[0]
                for value in values[1:]:
                    result = value if result else result
                return result
            if isinstance(node.op, ast.Or):
                result = values[0]
                for value in values[1:]:
                    result = result if result else value
                return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, names)
            for operation_node, comparator in zip(node.ops, node.comparators):
                right = evaluate(comparator, names)
                operations = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
                operation = next((fn for kind, fn in operations.items() if isinstance(operation_node, kind)), None)
                if operation is None or not operation(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*[evaluate(arg, names) for arg in node.args])
