import ast
import operator

def _evaluate(rule, values):
    tree = ast.parse(rule, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in ops:
                raise ValueError('unsupported expression')
            return ops[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.USub, ast.UAdd, ast.Not)):
            value = visit(node.operand)
            return -value if isinstance(node.op, ast.USub) else value if isinstance(node.op, ast.UAdd) else not value
        if isinstance(node, ast.BoolOp):
            result = visit(node.values[0])
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = visit(item)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = visit(right_node)
                fn = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                if fn is None or not fn(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
            values_list = [visit(arg) for arg in node.args]
            return min(values_list) if node.func.id == 'min' else max(values_list)
        raise ValueError('unsupported expression')
    return visit(tree)

def select_machines(records: list[dict[str, int | float]], rule: str) -> list[str]:
    return [record['id'] for record in records if _evaluate(rule, record)]

