import zipfile

def extract_translation_bundle(base_dir: str, archive_path: str, locale: str) -> list[str]:
    base = Path(base_dir).resolve()
    destination = (base / locale).resolve()
    try:
        destination.relative_to(base)
    except ValueError:
        raise ValueError('destination is outside base directory')
    written = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            target = (destination / info.filename).resolve()
            try:
                relative = target.relative_to(destination)
            except ValueError:
                raise ValueError('archive entry is outside destination')
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as source, target.open('wb') as output:
                output.write(source.read())
            written.append(relative.as_posix())
    return sorted(written)

