import hmac

def verify_license(document: str, signing_key: bytes, current_year: int) -> tuple[str, int]:
    parts = document.split('|')
    if len(parts) != 3:
        raise ValueError('invalid license document')
    license_id, year_text, signature = parts
    if not license_id or license_id.strip() != license_id:
        raise ValueError('invalid license identifier')
    if len(year_text) != 4 or not year_text.isdecimal():
        raise ValueError('invalid expiry year')
    if len(signature) != 64 or any((ch not in '0123456789abcdef' for ch in signature)):
        raise ValueError('invalid signature')
    expiry_year = int(year_text)
    payload = f'{license_id}|{year_text}'.encode()
    expected = hmac.new(signing_key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    if expiry_year < current_year:
        raise ValueError('expired license')
    return (license_id, expiry_year)

