import hmac
import json

def due_medication_reminders(envelope: str, key: bytes) -> list[dict[str, object]]:
    if '\n' not in envelope:
        raise ValueError('invalid envelope')
    supplied, payload = envelope.split('\n', 1)
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        records = json.loads(payload)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    return sorted((record for record in records if record.get('due') is True), key=lambda record: record['time'])

