import os

def write_seed_inventory(base_dir: str, relative_name: str, seeds: list[tuple[str, int]]) -> str:
    if not relative_name:
        raise ValueError('file name must not be empty')
    for name, quantity in seeds:
        if not isinstance(quantity, int) or quantity < 0:
            raise ValueError('quantity must be a non-negative integer')
    base = os.path.realpath(base_dir)
    result = os.path.realpath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath((base, result)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('file path is outside the base directory')
    os.makedirs(os.path.dirname(result), exist_ok=True)
    with open(result, 'w', encoding='utf-8') as handle:
        for name, quantity in sorted(seeds, key=lambda item: item[0]):
            handle.write(f'{name},{quantity}\n')
